ee:message.ee:set-payload:
          %dw 2.0
output multipart/form-data
---
{
  parts: {
    file: {
      headers: {
        "Content-Disposition": {
          "name": "file",
          "filename": vars.documentKey
        }
      },
      content: vars.documentContent
    },
    documentName: {
      headers: {
        "Content-Disposition": {
          "name": "documentName"
        }
      },
      content: vars.documentKey
    }
  }
}
